-- RLS for kon-members after the English rename: functions, triggers and policies come back with the new names.
--
-- The previous file dropped the old ones; between both files the tables stay closed, not open.

-- Policies, with the new names and the core's English helpers.
DROP POLICY IF EXISTS member_access_permitir ON member_access;
DROP POLICY IF EXISTS member_access_allow ON member_access;
